// What each release of the core changes in a company's factory folder, as
// code: `software-factory upgrade` runs the migrations of every release
// after the factory's version, in order. A change a company would otherwise
// have to make by hand comes with one here; what a migration cannot decide
// alone, it leaves to the owner, said in a line.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { COMPANY_FILE, findProducts, readCompany, saveCompany, } from "@software-factory/core";
import { trackedWith } from "../add-ons/switch.js";
import { moveOut } from "./move-out.js";
import { Refused } from "../refused.js";
export const MIGRATIONS = [
    {
        version: "0.2.0",
        about: "Products of a kind a kit now knows get that kit",
        run: kindsKitsNowKnow,
    },
    {
        version: "0.2.0",
        about: "Only the tracker in use is on",
        run: ({ root, extensions }) => {
            const company = companyOf(root);
            const tracked = trackedWith(company, extensions, company.tracker);
            if (sameList(tracked.without, company.without))
                return nothing();
            saveCompany(root, tracked);
            return { done: ["Switched off the trackers not in use."], left: [] };
        },
    },
    {
        version: "0.2.0",
        about: "The agents' ground rules name the board's cards",
        run: ({ root }) => addAfter(join(root, "AGENTS.md"), "`update-context`.", "software-factory card", " When the factory is connected to a board, work comes from its cards: `npx software-factory card` lists, plans and readies them (`npx software-factory card help`)."),
    },
    {
        version: "0.3.0",
        about: "The agents call the core pinned in the project, with npx",
        run: ({ root }) => replaceIn(join(root, "AGENTS.md"), /(?<!npx )`software-factory card/g, "`npx software-factory card", "The agents' ground rules call the pinned core with npx."),
    },
    {
        version: "0.5.0",
        about: "The agents' ground rules name the knowledge base's check command",
        run: ({ root }) => replaceIn(join(root, "AGENTS.md"), /run the knowledge base's checks\.(?! \(`npx)/, "run the knowledge base's checks (`npx software-factory check-docs`).", "The agents' ground rules name the command that checks the knowledge base."),
    },
    {
        version: "0.6.0",
        about: "The knowledge base joins the project's docs/; products are described next to their code",
        run: moveOut,
    },
    {
        version: "0.6.0",
        about: "The agents' ground rules point to docs/ for what the company knows",
        run: ({ root }) => replaceIn(join(root, "AGENTS.md"), /`context\//g, "`docs/", "The agents' ground rules point to docs/ for the knowledge base."),
    },
];
// A product described as other code that a kit now recognises becomes that
// kit's kind; the company's kits follow its products.
function kindsKitsNowKnow({ root, kits }) {
    const done = [];
    const left = [];
    const specific = kits.filter((kit) => !kit.fallback);
    for (const product of findProducts(root).products) {
        if (product.kind !== "other-code")
            continue;
        const kit = specific.find((one) => one.detect(product.folder) !== null);
        if (!kit)
            continue;
        const file = join(root, "products", product.id, "product.json");
        const data = JSON.parse(readFileSync(file, "utf8"));
        writeFileSync(file, `${JSON.stringify({ ...data, kind: kit.kind }, null, 2)}\n`);
        done.push(`${product.name} is now a ${kit.name} (it was other code).`);
        const blueprint = join(root, "products", product.id, "BLUEPRINT.md");
        if (!replaceKind(blueprint, kit.kind))
            left.push(`Say in ${product.name}'s BLUEPRINT.md that its kind is ${kit.kind}.`);
    }
    if (done.length > 0)
        keepKitsOfProducts(root, kits);
    return { done, left };
}
// The company's kits: one for each kind its products have.
function keepKitsOfProducts(root, kits) {
    const kinds = new Set(findProducts(root).products.map((p) => p.kind));
    const company = companyOf(root);
    saveCompany(root, {
        ...company,
        kits: kits.filter((kit) => kinds.has(kit.kind)).map((kit) => kit.id),
    });
}
function replaceKind(file, kind) {
    if (!existsSync(file))
        return false;
    const text = readFileSync(file, "utf8");
    const changed = text.replace(/^(- \*\*Kind:\*\* )other-code\b[^.\n]*/m, `$1${kind}`);
    if (changed === text)
        return false;
    writeFileSync(file, changed);
    return true;
}
// Adds text after a sentence of a file, once.
function addAfter(file, after, mark, text) {
    if (!existsSync(file))
        return nothing();
    const read = readFileSync(file, "utf8");
    if (read.includes(mark))
        return nothing();
    if (!read.includes(after))
        return {
            done: [],
            left: [`Add to factory/AGENTS.md:${text}`],
        };
    writeFileSync(file, read.replace(after, after + text));
    return { done: ["Named the board's cards in factory/AGENTS.md."], left: [] };
}
// Replaces what the pattern finds in a file, if anything.
function replaceIn(file, pattern, text, said) {
    if (!existsSync(file))
        return nothing();
    const read = readFileSync(file, "utf8");
    const changed = read.replace(pattern, text);
    if (changed === read)
        return nothing();
    writeFileSync(file, changed);
    return { done: [said], left: [] };
}
export function companyOf(root) {
    const read = readCompany(join(root, COMPANY_FILE));
    if ("problem" in read)
        throw new Refused(read.problem);
    return read.company;
}
function sameList(a, b) {
    const sorted = (list) => [...list].sort((x, y) => x.localeCompare(y)).join();
    return sorted(a) === sorted(b);
}
function nothing() {
    return { done: [], left: [] };
}
